package mrpapermoon.whisper.mesh.transformationimport androidx.room.TypeConverterimport kotlinx.serialization.decodeFromByteArrayimport kotlinx.serialization.encodeToByteArrayimport kotlinx.serialization.protobuf.ProtoBufimport mrpapermoon.whisper.mesh.db.NetworkMessageEntityimport mrpapermoon.whisper.mesh.db.WhispererEntity@Suppress("unused")class RoomTypeConverters {	@TypeConverter	fun serialize(message: NetworkMessageEntity): ByteArray =		ProtoBuf.encodeToByteArray(message)	@TypeConverter	fun deserializeNetworkMessageEntity(bytes: ByteArray): NetworkMessageEntity =		ProtoBuf.Default.decodeFromByteArray(bytes)	@TypeConverter	fun serialize(message: WhispererEntity): ByteArray =		ProtoBuf.encodeToByteArray(message)	@TypeConverter	fun deserializeWhispererEntity(bytes: ByteArray): WhispererEntity =		ProtoBuf.Default.decodeFromByteArray(bytes)	@TypeConverter	fun serialize(whisperers: Set<ByteArray>): ByteArray =		ProtoBuf.encodeToByteArray(whisperers)	@TypeConverter	fun deserializeByteArraySet(bytes: ByteArray): Set<ByteArray> =		ProtoBuf.Default.decodeFromByteArray(bytes)}